/**
 * 构建 /system/profile/updatePwd 请求体：入参全部加密（禅道 Task 2336）
 *
 * 后端要求该接口所有入参按 /security/auth/login 的方式加密后传输，
 * 不允许任何密码字段（含确认密码）出现明文。这里按传入对象逐字段加密，
 * 并原样保留字段名，后续新增入参也会自动被加密，不会遗漏。
 *
 * @param {Record<string, string>} params 形如 { oldPwd, newPwd, confirmPassword }
 * @returns {Record<string, string>} 全部为密文的请求体
 */
export function buildUpdatePwdBody(params = {}) {
  return Object.keys(params).reduce((body, key) => {
    body[key] = encrypt(params[key])
    return body
  }, {})
}

