/**
 * A: oldPassword / newPassword / confirmPassword（与产品 2.0、淮安物管一致）
 * B: oldPwd / newPwd / rePwd
 */
/** 淮安存量房后端约定为 oldPwd / newPwd / rePwd；其它部署可改为 'A' */
export const UPDATE_PWD_FIELD_SCHEME = 'B'

/**
 * AES 加密，与登录接口保持一致
 * @param {string} text
 * @returns {string}
 */
export function encrypt(text) {
  if (text == null || text === '') {
    return text
  }

  return CryptoJS.AES.encrypt(text, SECRET_PASSPHRASE, {
    mode: CryptoJS.mode.ECB,
    padding: CryptoJS.pad.Pkcs7,
    iv: IV,
  }).toString()
}

/**
 * 构建 /system/profile/updatePwd 请求体（仅含加密后的密码字段）
 * @param {{ oldPwd: string, newPwd: string, confirmPassword: string }} passwords
 * @param {'A' | 'B'} [scheme]
 */
export function buildUpdatePwdBody({ oldPwd, newPwd, confirmPassword }, scheme = UPDATE_PWD_FIELD_SCHEME) {
  const oldCipher = encrypt(oldPwd)
  const newCipher = encrypt(newPwd)
  const confirmCipher = encrypt(confirmPassword)

  if (scheme === 'B') {
    return {
      oldPwd: oldCipher,
      newPwd: newCipher,
      rePwd: confirmCipher,
    }
  }

  return {
    oldPassword: oldCipher,
    newPassword: newCipher,
    confirmPassword: confirmCipher,
  }
}

